import{_ as a,c as n,o as t,ag as i}from"./chunks/framework.Vyheyqg9.js";const m=JSON.parse('{"title":"Collections and bounded queues","description":"","frontmatter":{},"headers":[],"relativePath":"practice/cs-foundations/collections-and-queues.md","filePath":"practice/cs-foundations/collections-and-queues.md"}'),r={name:"practice/cs-foundations/collections-and-queues.md"};function s(o,e,c,d,l,u){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="collections-and-bounded-queues" tabindex="-1">Collections and bounded queues <a class="header-anchor" href="#collections-and-bounded-queues" aria-label="Permalink to “Collections and bounded queues”">​</a></h1><p><strong>Learner status: still required.</strong> Use the <a href="./#evidence-for-every-checkpoint">shared evidence requirements</a>.</p><h2 id="cs-p04-bounded-fifo" tabindex="-1"><span class="hub-section-number">1 </span>CS-P04: bounded FIFO <a class="header-anchor" href="#cs-p04-bounded-fifo" aria-label="Permalink to “1 CS-P04: bounded FIFO”">​</a></h2><p><strong>Prerequisites:</strong> CS-P01, <a href="./../../cs-foundations/data-structures.html">structure selection</a>, array indices, references and modulo arithmetic.</p><p><strong>Scope:</strong> a fixed-capacity FIFO, capacity 1–200 for practice. Define enqueue/dequeue/size, reject full enqueue and empty dequeue, and permit undefined payloads by tracking occupancy separately. No resizing, async waiting or general linked-list package is required.</p><p><strong>Observable acceptance:</strong></p><ul><li>Capacity-3 sequence A/B/C → dequeue A → enqueue D drains B/C/D. Repeat wraparound many times and test capacity 1.</li><li>Invalid capacity, full enqueue and empty dequeue reject without changing existing order/size.</li><li>Mixed deterministic operations agree with a simple small array model; include object identity and undefined payloads.</li><li>Maintain <code>0≤size≤capacity</code>, valid head and logical-to-physical slot mapping. Clear consumed slots so the queue does not retain removed payload references; inspect ownership deliberately rather than demanding a GC event at a fixed time.</li><li>Explain construction O(capacity), per-operation O(1) in the fixed-array model, retained storage and difference from repeated shift/head-index queues.</li></ul><p><strong>Failure cases:</strong> stale tail after emptying a linked alternative; wraparound overwriting live entries; using undefined as both data and empty sentinel; accidental retention. Explain known-node deletion versus the O(n) search for a linked-list predecessor and when a deque would be appropriate.</p><p><strong>Evidence:</strong> model traces, observed rejection/state, invariant/progress explanation and reference-lifetime reasoning. A queue does not limit bytes reachable from payloads or make consumers run concurrently.</p><h2 id="cache-extension" tabindex="-1"><span class="hub-section-number">2 </span>Cache extension <a class="header-anchor" href="#cache-extension" aria-label="Permalink to “2 Cache extension”">​</a></h2><p><strong>Optional, existing exercise relocated from General ES6. Prerequisites:</strong> Map equality, undefined/absence, mutation and ownership; no WeakMap GC timing requirement.</p><p>Implement a bounded Map cache with a documented FIFO or LRU policy. Acceptance: distinguish missing from stored undefined; show object identity and NaN/zero cases; verify object key order; reject unsupported serialized keys; enforce an entry limit and document hit promotion/eviction. Explain why WeakMap collection cannot be required at a deterministic time and verify symbol support against any chosen runtime matrix.</p><p>Test capacity 1, repeated updates, eviction order, clear and mutation after caching. Record the key/equality policy, stale-result counterexample/fix, runtime results and entry-count versus retained-byte limits. This reuses the <a href="./retained-exercises.html#existing-collection-exercise">retained original requirements</a>; it is not a second core assignment.</p>',13)])])}const h=a(r,[["render",s]]);export{m as __pageData,h as default};
